from fractions import Fraction

def works(a, eps, delta):
    for k in range(1, 100):
        t = delta * Fraction(k, 100)
        if abs((a + t)**2 - a**2) >= eps or abs((a - t)**2 - a**2) >= eps:
            return False
    return True

n = int(input())
for i in range(1, n + 1):
    a = int(input())
    eps = Fraction(input())
    K = 2 * abs(a) + 1
    delta = eps / K
    if delta > 1:
        delta = Fraction(1)
    s = Fraction(1)
    while not works(a, eps, s):
        s = s / 2
    print(f"problem {i}: K = {K}, delta = {delta}, search = {s}")

from fractions import Fraction

def far_works(c, d, r, eps, N):
    for k in range(1, 201):
        x = N + Fraction(k, 10)
        if abs((c * x + d) / (x + r) - c) >= eps:
            return False
    return True

n = int(input())
for i in range(1, n + 1):
    c = int(input())
    d = int(input())
    r = int(input())
    eps = Fraction(input())
    gap = abs(d - c * r)
    if gap == 0:
        print(f"problem {i}: any N works")
    else:
        N = gap / eps - r
        s = 1
        while not far_works(c, d, r, eps, s):
            s = 2 * s
        print(f"problem {i}: N = {N}, search = {s}")
